window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
window.gtag = gtag;
gtag('consent', 'default', {
  ad_storage: 'granted',
  ad_user_data: 'granted',
  ad_personalization: 'granted',
  analytics_storage: 'granted',
  functionality_storage: 'granted',
  security_storage: 'granted'
});
gtag('consent', 'default', {
  ad_storage: 'denied',
  ad_user_data: 'denied',
  ad_personalization: 'denied',
  analytics_storage: 'denied',
  functionality_storage: 'granted',
  security_storage: 'granted',
  region: ["AT","BE","BG","HR","CY","CZ","DK","EE","FI","FR","DE","GR","HU","IE","IT","LV","LI","LT","LU","MT","NL","PL","PT","RO","SK","SI","ES","SE","IS","NO","GB","CH"],
  wait_for_update: 500
});
try {
  var c = localStorage.getItem("stairway:consent:v1");
  if (c === 'granted' || c === 'denied') {
    gtag('consent', 'update', {
      ad_storage: c, ad_user_data: c, ad_personalization: c, analytics_storage: c
    });
  }
} catch (e) {}
gtag('set', 'url_passthrough', true);
gtag('set', 'ads_data_redaction', true);
gtag('js', new Date());
gtag('config', "G-Q3LMTFT0L8", (function () {
  var cfg = { send_page_view: false };
  try {
    var url = new URL(window.location.href);
    ["session_id","session","token","email","key"].forEach(function (k) {
      if (url.searchParams.has(k)) url.searchParams.set(k, 'redacted');
    });
    cfg.page_location = url.toString();
  } catch (e) {}
  return cfg;
})());
